<?php
$base = '/fleet/vehicles/' . (int) $vehicle['id'] . '/damage-repairs/' . (int) $job['id'];
$old = $replacement ?? null;
$data = $formData;
$kind = $old['kind_code'] ?? $data['kind_code'] ?? 'invoice';
$target = $old === null ? $base . '/costs' : $base . '/costs/' . (int) $old['id'] . '/replace';
$key = $data['command_key'] ?? \App\Services\Fleet\VehicleDamageRepairService::commandKey();
?>
<section class="vehicle-damage-work"><p><a href="<?= $base ?>#repair-costs">Back to repair job</a></p><h1><?= $old === null ? 'Record vendor-side repair cost fact' : 'Correct recorded cost fact' ?></h1>
<?php if ($old !== null): ?><p>Original <?= esc($old['kind_code']) ?>: USD <?= esc($old['amount']) ?>, <?= esc($old['occurred_on']) ?>, <?= esc($old['vendor_snapshot']) ?>. A replacement preserves the original and voids it atomically.</p><?php endif; ?>
<p>Enter the source amount and occurrence date. Select an existing matching document or upload verified binary evidence. Credits and refunds retain their original parent reference.</p>
<?php if ($duplicateReview !== null): ?><section aria-labelledby="duplicate-review-title"><h2 id="duplicate-review-title">Duplicate review</h2><?php if ($duplicateReview['candidates'] === []): ?><p>No candidates found for this reviewed source and amount/date.</p><?php else: ?><p>Possible duplicates require review. These records remain separate.</p><ul><?php foreach ($duplicateReview['candidates'] as $candidate): ?><li><?= esc(ucwords(str_replace('_', ' ', $candidate['domain']))) ?> <?= (int) $candidate['id'] ?> &middot; <?= esc((string) ($candidate['amount'] ?? 'Unknown amount')) ?> &middot; <?= esc((string) ($candidate['occurred_on'] ?? 'Unknown date')) ?> &middot; <?= esc((string) ($candidate['vendor'] ?? 'Vendor identity requires review')) ?></li><?php endforeach; ?></ul><?php endif; ?></section><?php endif; ?>
<form action="<?= $target ?>" method="post" enctype="multipart/form-data">
<?= csrf_field() ?><input type="hidden" name="command_key" value="<?= esc($key, 'attr') ?>"><input type="hidden" name="expected_version" value="<?= (int) ($data['expected_version'] ?? $job['version']) ?>">
<?php if ($old !== null): ?><input type="hidden" name="cost_entry_id" value="<?= (int) $old['id'] ?>"><input type="hidden" name="expected_entry_state" value="<?= esc($repairCosts['entry_states'][$old['id']] ?? '', 'attr') ?>"><input type="hidden" name="kind_code" value="<?= esc($kind, 'attr') ?>"><label>Correction reason<textarea name="reason" required maxlength="2000"><?= esc((string) ($data['reason'] ?? '')) ?></textarea></label>
<?php else: ?><label>Fact kind<select name="kind_code"><?php foreach (\Config\VehicleDamageRepairCosts::KINDS as $code => $label): ?><option value="<?= esc($code, 'attr') ?>" <?= $code === $kind ? 'selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label><?php endif; ?>
<div class="damage-form-grid issue-filters"><label>Source amount in USD<input name="amount" inputmode="decimal" required value="<?= esc((string) ($data['amount'] ?? ''), 'attr') ?>"></label><label>Currency<select name="currency"><option value="USD">USD</option></select></label><label>Occurred on<input type="date" name="occurred_on" required value="<?= esc((string) ($data['occurred_on'] ?? ''), 'attr') ?>"></label>
<label>Known vendor<select name="vendor_company_id"><option value="">Use frozen source vendor text</option><?php foreach ($vendors as $vendor): ?><option value="<?= (int) $vendor['id'] ?>" <?= (string) ($data['vendor_company_id'] ?? '') === (string) $vendor['id'] ? 'selected' : '' ?>><?= esc($vendor['name']) ?></option><?php endforeach; ?></select></label><label>Source vendor name<input name="vendor_snapshot" required maxlength="190" value="<?= esc((string) ($data['vendor_snapshot'] ?? ''), 'attr') ?>"></label><label>Vendor reference<input name="vendor_reference" maxlength="120" value="<?= esc((string) ($data['vendor_reference'] ?? ''), 'attr') ?>"></label>
<label>Original parent fact<select name="related_cost_entry_id"><option value="">None (invoice or standalone payment)</option><?php foreach ($repairCosts['entries'] as $parent): if (! in_array($parent['kind_code'], ['invoice', 'payment'], true)) { continue; } ?><option value="<?= (int) $parent['id'] ?>" <?= (string) ($data['related_cost_entry_id'] ?? '') === (string) $parent['id'] ? 'selected' : '' ?>><?= esc($parent['kind_code']) ?> <?= (int) $parent['id'] ?> / USD <?= esc($parent['amount']) ?> / <?= esc($parent['status_code']) ?></option><?php endforeach; ?></select></label>
<label>Existing supporting document<select name="repair_document_id"><option value="">New upload</option><?php foreach ($repairDocuments as $doc): if ($doc['archived_at'] !== null || ! in_array($doc['kind_code'], \Config\VehicleDamageRepairCosts::DOCUMENT_KINDS, true)) { continue; } ?><option value="<?= (int) $doc['id'] ?>" <?= (string) ($data['repair_document_id'] ?? '') === (string) $doc['id'] ? 'selected' : '' ?>><?= esc($doc['kind_code']) ?> <?= (int) $doc['id'] ?> / <?= esc($doc['label'] ?? $doc['content_original_filename'] ?? 'Supporting document') ?></option><?php endforeach; ?></select></label>
<?php foreach ($documentStates as $id => $state): ?><input type="hidden" name="document_states[<?= (int) $id ?>]" value="<?= esc($state, 'attr') ?>"><?php endforeach; ?>
<label>New supporting document<input type="file" name="repair_document" accept="application/pdf,image/jpeg,image/png,image/webp"></label><label>Source label<input name="document[label]" maxlength="190" value="<?= esc((string) ($data['document']['label'] ?? ''), 'attr') ?>"></label></div>
<?php if (isset($data['document']['descriptor'])): ?><p>Reselect the same reviewed binary before saving. Its content identity must match.</p><?php foreach ($data['document']['descriptor'] as $field => $value): ?><input type="hidden" name="document[descriptor][<?= esc($field, 'attr') ?>]" value="<?= esc((string) $value, 'attr') ?>"><?php endforeach; ?><?php endif; ?>
<label>Note<textarea name="note" maxlength="2000"><?= esc((string) ($data['note'] ?? '')) ?></textarea></label>
<label><input type="checkbox" name="performed_work_confirmed" value="1" <?= ($data['performed_work_confirmed'] ?? '') === '1' ? 'checked' : '' ?>> Invoice represents verified work performed (required for invoices).</label><label><input type="checkbox" name="verified_zero_confirmed" value="1" <?= ($data['verified_zero_confirmed'] ?? '') === '1' ? 'checked' : '' ?>> Source explicitly verifies a zero-dollar invoice.</label>
<label><input type="checkbox" name="vendor_mismatch_confirmed" value="1" <?= ($data['vendor_mismatch_confirmed'] ?? '') === '1' ? 'checked' : '' ?>> I reviewed a source vendor differing from the job vendor.</label><label>Vendor mismatch reason<textarea name="vendor_mismatch_reason" maxlength="2000"><?= esc((string) ($data['vendor_mismatch_reason'] ?? '')) ?></textarea></label>
<?php if ($duplicateReview !== null): ?><input type="hidden" name="duplicate_review_fingerprint" value="<?= esc($duplicateReview['fingerprint'], 'attr') ?>"><?php endif; ?>
<label><input type="checkbox" name="duplicate_review_confirmed" value="1"> I reviewed possible duplicates and confirm this separate fact.</label><label>Duplicate review reason<textarea name="duplicate_review_reason" maxlength="2000"><?= esc((string) ($data['duplicate_review_reason'] ?? '')) ?></textarea></label>
<label><input type="checkbox" name="confirmed" value="1" required> This is the stated vendor-side monetary fact supported by the selected evidence.</label>
<button type="submit" formaction="<?= $base ?>/costs/review" formnovalidate>Review duplicate candidates</button> <button type="submit"><?= $old === null ? 'Record fact' : 'Save atomic replacement' ?></button></form></section>
